static int val_a = 5;
static int val_b = 10;

// Array of two pointers to integers
static int* storage_ptrs[2] = { &val_a, &val_b };

// Complex Declaration using Storage Class Specifier:
// PTR: static pointer to an array of 2 pointers to ints
static int* (*PTR)[2] = &storage_ptrs;

// Example Usage: Accesses val_b
int accessed = *(*PTR)[1]; // accesses 10

// Alternative example: pointer to a register-allocated function pointer
extern int func(int);
register int (*volatile volatile_func_ptr)(int) = func;
